<script setup lang="ts">
import { guides } from '~/data/guides'
const route = useRoute()
const guide = guides.find(g => g.slug === route.params.slug)
if (!guide) throw createError({ statusCode: 404, statusMessage: '記事が見つかりません' })
usePageSeo(guide.title, guide.description, '/guides/'+guide.slug)
useHead({ script: [{ type: 'application/ld+json', innerHTML: JSON.stringify({ '@context':'https://schema.org', '@type':'BreadcrumbList', itemListElement:[{'@type':'ListItem',position:1,name:'ホーム',item:'https://www.myhobby.jp/'},{'@type':'ListItem',position:2,name:'選び方ガイド',item:'https://www.myhobby.jp/guides'},{'@type':'ListItem',position:3,name:guide.title,item:'https://www.myhobby.jp/guides/'+guide.slug}] }) }] })
</script><template><article v-if="guide" class="reading"><nav aria-label="パンくず"><NuxtLink to="/">ホーム</NuxtLink> / <NuxtLink to="/guides">選び方ガイド</NuxtLink></nav><p class="eyebrow">{{guide.tag}} / BUYING GUIDE</p><h1>{{guide.title}}</h1><p class="lead">{{guide.lead}}</p><p class="byline">編集：<NuxtLink to="/about">MyHobby / wakaki</NuxtLink> · 購入前の確認ガイド</p><aside class="toc"><strong>この記事の内容</strong><ol><li v-for="(s,i) in guide.sections" :key="i"><a :href="'#section-'+i">{{s[0]}}</a></li></ol></aside><section v-for="(s,i) in guide.sections" :id="'section-'+i" :key="i"><h2>{{s[0]}}</h2><p>{{s[1]}}</p></section><section v-if="guide.sources.length"><h2>確認に使える公式情報</h2><ul><li v-for="source in guide.sources" :key="source[1]"><a :href="source[1]" rel="noopener" target="_blank">{{source[0]}} ↗</a></li></ul></section><aside class="article-cta"><h2>確認するポイントが分かったら。</h2><p>掲載商品の販売ページで、仕様・保証・価格を照らし合わせましょう。</p><NuxtLink to="/#products" class="button">掲載商品を確認する →</NuxtLink></aside><h2>あわせて読みたい</h2><p v-for="g in guides.filter(g => g.slug !== guide.slug)" :key="g.slug"><NuxtLink :to="'/guides/'+g.slug">{{g.title}} →</NuxtLink></p></article></template>